/* Roadtripica offline road-trip guide. Own-written, conservative, general guidance. See SOURCES-guide.md for what was and was not source-checked.
   item: {id, cat, t, sum, steps[], check[], list[], warn, links[{t,u}], gen:true for "general description, not source-checked"} */
window.RTGUIDE = {
  cats: [
    ['before', 'Before you go'], ['kids', 'Kids in the car'], ['drive', 'Long-haul driving'], ['trouble', 'Breakdown or crash'],
    ['weather', 'Weather'], ['remote', 'Remote roads'], ['rv', 'RV and trailer'], ['money', 'Money'], ['food', 'Eating'],
    ['games', 'Games'], ['pack', 'Packing'], ['scenic', 'Scenic routes']
  ],
  asof: '2026-10',
  items: [
    /* ---------------- BEFORE YOU GO ---------------- */
    { id: 'car-check', cat: 'before', t: 'Car checklist (a week before)', sum: 'A calm hour in the driveway beats a breakdown in the desert.',
      steps: ['Do this a week out, so there is time to fix what you find.', 'Tires: check pressure when the tires are cold (before driving), using the number on the sticker inside the driver door or in the manual, not the number on the tire itself. Look at tread and sidewalls for cracks, bulges or nails.', 'Check the spare too (if you have one): pressure, and that the jack and wheel wrench are in the car. If you have a sealant kit or inflator instead, read how it works now.', 'Fluids: engine oil level, coolant (only check the reservoir when the engine is cold), washer fluid. Top up what is low. If a service is due, do it before leaving.', 'Lights: sit in the car with someone outside. Check headlights, brake lights, turn signals and hazards.', 'Wipers and windshield: replace streaky blades, and clear any chips that could grow.', 'Battery: if it is more than a few years old or starts slowly, have a shop test it.', 'If the car has a warning light on, get it looked at before a long trip.'],
      check: ['Tire pressure set (cold)', 'Tread and sidewalls look good', 'Spare, jack and wheel wrench present', 'Oil and coolant levels OK', 'Washer fluid full', 'Lights and signals work', 'Wipers good', 'Battery tested if old', 'No warning lights', 'Service due? Done'],
      links: [{ t: 'NHTSA: tires', u: 'https://www.nhtsa.gov' }] },
    { id: 'documents', cat: 'before', t: 'Documents and cards', sum: 'Paper copies matter when the phone is dead or has no signal.',
      steps: ['Gather these in one folder or pouch, kept in the car (not in a phone only).', 'Make a photo of each on your phone as a back-up, and keep one printed set separately from the originals.', 'If crossing a border, check the entry rules for every traveler (passports, children travelling with one parent, vehicle papers, insurance) with the official government site well before leaving.'],
      check: ['Driver license for each driver', 'Vehicle registration and proof of insurance', 'Roadside assistance membership details', 'Insurance company claim number', 'Rental agreement if renting', 'Park or campground reservations printed', 'Medical insurance cards', 'List of medicines and allergies for each person', 'Emergency contacts on paper', 'Passports if crossing a border'] },
    { id: 'emergency-kit', cat: 'before', t: 'Emergency kit for the car', sum: 'Small, always in the trunk.',
      steps: ['Pack it once and leave it in the car for the whole trip.', 'Add season items: ice scraper and warm blankets in winter; extra water and sun shade in summer.', 'Check batteries and the first-aid kit contents before every long trip.'],
      check: ['Jumper cables or a jump starter pack', 'Flashlight or headlamp with spare batteries', 'First-aid kit', 'Reflective triangles or flares', 'High-visibility vest', 'Tire inflator or sealant kit', 'Basic tools, duct tape, zip ties', 'Gloves and a rag', 'Extra water (at least a gallon per person for remote trips)', 'Snacks that keep', 'Blankets', 'Phone charger and power bank', 'Paper map or atlas of your route', 'Fire extinguisher (small, rated for vehicles)', 'Rain ponchos', 'Whistle'] },
    { id: 'roadside', cat: 'before', t: 'Roadside assistance', sum: 'Know who you will call before you need them.',
      steps: ['Find out what you have: your car insurer, your car maker, a credit card, or a motor club may include towing. Read how many miles of tow and how many calls per year are covered.', 'Save the phone number in your phone AND write it on paper in the glove box. Dead phone, no help.', 'Know your location in words: highway name, direction of travel, nearest mile marker or exit. Many phones can show coordinates in the map app.', 'In a remote area, check that your plan covers the places you will go. Some do not cover unpaved roads.'] },
    { id: 'phone', cat: 'before', t: 'Phone, power and offline maps', sum: 'Phones are your map, camera and rescue line. Keep them alive.',
      steps: ['Download offline maps for your whole route and a wide margin around it, while on Wi-Fi at home. Check that they still open with airplane mode on.', 'Also save the route and key addresses (lodging, campground, parks) as text or screenshots.', 'Car charger or a cable that works with your phone, and a charged power bank. Bring a spare cable.', 'A phone holder that does not block your view. Set up the route before you start driving; do not handle the phone while driving.', 'Turn on emergency alerts and share your location with a trusted person for the trip.', 'Keep at least one paper map or road atlas in the car. It never runs out of battery.'] },
    { id: 'kids-kit', cat: 'before', t: 'Kids activity kit', sum: 'Pack it in a bag within the children\'s reach.',
      steps: ['One small bag per child, packed with a few new-to-them items and a few old favourites. Keep a few surprises for later in the day.', 'Choose quiet things that do not roll under seats.'],
      check: ['Colouring books, crayons or pencils (a clipboard works as a desk)', 'Sticker books or reusable sticker scenes', 'Small notebook for a trip diary', 'Playing cards', 'Magnetic travel games', 'Audio stories or music downloaded', 'Headphones for kids if they use devices', 'Favourite stuffed toy or blanket', 'Wet wipes and tissues', 'Sick bags and spare clothes', 'Water bottle each', 'Small snacks that do not crumble', 'Printed bingo from the Journal tab'] },
    { id: 'pets', cat: 'before', t: 'Travelling with pets', sum: 'Safe in the car, safe at stops.',
      warn: 'Never leave a pet (or a child) alone in a parked car. The inside of a car can become dangerous within minutes, even on a mild day with the windows cracked.',
      steps: ['Restrain the pet: a secured crate or a harness made for car travel. A loose pet is unsafe for everyone in a sudden stop.', 'Bring: leash, water and bowl, food, waste bags, vaccination records, medications, a recent photo, and ID tags with a phone number that works on the trip.', 'Plan breaks every few hours for water and a walk. Use a leash at every stop.', 'Check that each place you will stay allows pets and what fees or rules apply.', 'Hot pavement burns paws. If you cannot hold the back of your hand on it for several seconds, it is too hot.', 'If your pet gets sick easily in cars, ask your vet before the trip.'] },

    /* ---------------- KIDS ---------------- */
    { id: 'kid-stops', cat: 'kids', t: 'Stops, pace and the long day', sum: 'A slower plan usually arrives happier.',
      steps: ['Plan a stop about every two hours, or sooner for little ones. Shorter drive days (about 4 to 6 hours of driving) make it fun for kids; very long days are best split in two.', 'Make stops count: a playground, a picnic table, a field to run in. Ten to fifteen minutes of running lets out a lot of energy.', 'Drive during nap time for babies and toddlers if you can, and eat at normal meal times where possible.', 'Keep a few little surprises (a new book, a favourite snack) for the hour when everyone is tired.', 'Everyone uses the toilet at every stop, even when they say they do not need to.', 'Give older children a job: navigator, snack manager, photographer, mile counter.'] },
    { id: 'carsick', cat: 'kids', t: 'Car sickness basics', sum: 'Common in children; small changes help. No drug doses here.',
      steps: ['Seat the child where they can see out the front window. Avoid sitting them with a view of only the side window.', 'Keep the car cool with fresh air; a stuffy car makes it worse.', 'Avoid reading, screens and close-up activities while moving. Use audio stories, singing and looking-out games instead.', 'Eat light before and during. Avoid big greasy meals. Plain crackers and water are good.', 'Smooth driving: gentle braking and acceleration, careful on curvy roads, plan breaks before the winding part.', 'Early signs: quiet, pale, sweaty, yawning. Pull over safely at the first sign for fresh air, not after.', 'Keep a sick bag, wipes and a change of clothes within reach.', 'If the problem is frequent or severe, talk to your doctor or pharmacist about what is safe for your child before the trip. Do not guess at medicines or doses.'] },
    { id: 'snacks', cat: 'kids', t: 'Snack and meal plan', sum: 'Less crumbs, fewer meltdowns.',
      warn: 'Choking risk: young children should be seated and watched when eating, not eating while the car is moving on bumpy roads. Skip whole nuts, whole grapes, hard candy and popcorn for little children.',
      steps: ['Pack a cooler for the day with fruit, cheese sticks, sandwiches, vegetables and water. Keep the cooler in the cabin, not a hot trunk.', 'Dry snacks in a box: crackers, cereal, dried fruit cut small, pretzels. Pick items that do not melt or stain.', 'Bring a water bottle each and refill at every stop. Skip too many sweet drinks.', 'Check for allergies at each stop and pack safe snacks for anyone who needs them.', 'Wipes, a trash bag and a small towel keep the car tidy.'] },
    { id: 'carseat', cat: 'kids', t: 'Car seat reminders', sum: 'Follow your seat\'s manual and your local law.',
      warn: 'Never leave a child alone in a parked car, even for a minute. Rules about child seats differ by state or country; the law where you are driving applies.',
      steps: ['Read the car seat manual and the vehicle manual. They tell you the seat\'s height and weight limits and how to install it.', 'Keep a child in each stage of seat (rear-facing, forward-facing with a harness, booster) until they have reached the limit of that seat, not just when they get tired of it.', 'Install tightly: the seat should barely move side to side at the belt path. Harness snug, with the chest clip at armpit level.', 'Avoid bulky winter coats under the harness. Put the coat on over the buckled harness or use a blanket.', 'Children are generally safest in the back seat. Check the law for where you are driving.', 'Renting a car? Ask for a seat in advance or bring your own; do not use a seat that has been in a crash or is expired.', 'Many fire stations and hospitals offer free car seat checks by a certified technician; look for one before your trip.'],
      links: [{ t: 'NHTSA: car seats', u: 'https://www.nhtsa.gov' }] },
    { id: 'screen-free', cat: 'kids', t: 'Entertainment plan', sum: 'Mix quiet, loud, screen and no-screen.',
      steps: ['Split the day: talking games in the morning, audio story after lunch, quiet time or movie in the afternoon slump.', 'Download everything before leaving: stories, music, movies, games. Do not rely on streaming.', 'Rotate things. Pull out the new bag at the start of each leg.', 'Give each child a disposable camera or a phone and a small photo mission such as "find five red things".', 'Let kids choose the playlist in turns.'] },

    /* ---------------- DRIVING ---------------- */
    { id: 'fatigue', cat: 'drive', t: 'Fatigue: signs and what to do', sum: 'Drowsy driving is dangerous. Stop before you are in trouble.',
      warn: 'Caffeine and loud music are short-term tricks. The real fix is sleep. If you notice any sign below, find a safe place and stop.',
      steps: ['Warning signs: frequent yawning, heavy eyelids, drifting from the lane, missing an exit or not remembering the last miles, hitting the rumble strip, jerky corrections.', 'Pull off at a rest area or parking lot (never the shoulder of a fast road). Take a nap of about 20 minutes, or sleep at a motel.', 'Take a break every two hours or about every 100 miles, even if you feel fine. Walk, stretch and drink water.', 'Share the driving. Swap before the driver is tired, not after.', 'Get a normal night of sleep before a long drive. Skip alcohol and check medicine labels for drowsiness warnings.', 'Be realistic with the day plan: a long day on top of no sleep is when problems happen.'],
      links: [{ t: 'NHTSA: drowsy driving', u: 'https://www.nhtsa.gov' }] },
    { id: 'night', cat: 'drive', t: 'Night driving', sum: 'Visibility, wildlife and tired eyes.',
      steps: ['Clean the windshield (inside and out) and headlights. Dim the dash lights.', 'Slow down: your headlights do not show you far enough to stop at high speed. Use high beams when no traffic is near and dip them for other cars.', 'In rural areas, animals cross at dusk and dawn. Scan the road edges for reflecting eyes. If an animal is in the road, brake firmly in your lane and do not swerve into traffic.', 'Avoid driving the longest hours of the night if you can; the hours after midnight are the hardest.', 'Plan to arrive before dark in unfamiliar or remote areas where check-in or fuel may be closed.'] },
    { id: 'mountain', cat: 'drive', t: 'Mountain passes and long descents', sum: 'Use the engine to brake, not only the brakes.',
      steps: ['Before a long downhill, shift to a lower gear (or use the low gear or "manual" mode on an automatic) and let the engine hold your speed. Follow signs about grade and speed.', 'Brake in short, firm presses rather than riding the brakes. Constant braking overheats them and they can fade.', 'If the brake pedal feels soft or you smell a hot, burning odour, do not keep going. Use a pullout and let them cool.', 'Going uphill, watch the temperature gauge. If it climbs, turn the air conditioning off and the heater on, and pull over safely.', 'Let faster traffic pass at pullouts. Keep a larger gap on switchbacks.', 'Fuel up before a long climb where stations are far apart. Altitude can reduce engine power a little and headaches are common for people; take it easy and drink water.'] },
    { id: 'winter', cat: 'drive', t: 'Winter driving and chains', sum: 'General guidance. Always check the road agency first.',
      warn: 'Before you leave, check road conditions and chain requirements with the state transportation department (search "<state> DOT road conditions"). Conditions change hour to hour. If it is bad, wait.',
      steps: ['Ask yourself if the trip can wait. Leave extra time and keep your tank at least half full.', 'Tires with good tread. In areas that require chains or traction devices, carry the right type for your tire size and practice putting them on at home in daylight, not on the roadside in a storm.', 'Slow down. Everything takes longer on snow and ice: accelerating, stopping and turning. Leave several times the usual following distance.', 'Brake gently, steer gently. If you skid, ease off the gas, look and steer where you want to go, and do not stomp the brake.', 'Clear all snow and ice from the windows, lights, mirrors and the roof before driving.', 'Keep the exhaust pipe clear of snow whenever the engine is running.', 'If stranded: stay with the car, call for help, run the engine only briefly for heat while the exhaust pipe is clear, and crack a window. Make the car visible with a bright cloth.', 'Winter kit: blankets or sleeping bag, warm hats and gloves, boots, shovel, ice scraper, sand or cat litter for traction, food, water, flashlight, phone charger.'] },

    /* ---------------- TROUBLE ---------------- */
    { id: 'breakdown', cat: 'trouble', t: 'If the car breaks down', sum: 'Get everyone safe first, then sort out the car.',
      steps: ['Turn on your hazard lights straight away.', 'Steer smoothly to the right shoulder, as far from traffic as possible. On a bend or hill crest, try to roll past it to where others can see you. A parking lot or exit ramp is best.', 'Stop, set the parking brake, and stay buckled while traffic whizzes by.', 'On a busy highway it is usually safest to stay in the car with your seat belt on and call for help. If you must leave, exit on the side away from traffic and stand well off the road, behind a barrier, with children and pets.', 'Call your roadside assistance. Give your location in words (highway, direction, mile marker, exit).', 'Place reflective triangles only if it is safe and the road is not busy; otherwise do not risk it.', 'Lift the hood and tie a cloth to the mirror or antenna to show you need help.', 'Do not accept a ride or help from strangers who do not offer through your assistance service. Stay in contact with a trusted person and share your location.', 'If you feel unsafe, call 911.'] },
    { id: 'crash', cat: 'trouble', t: 'If you are in a crash', sum: 'People first, then paper.',
      steps: ['Stop, turn the engine off, and turn on the hazards. Check yourself and your passengers.', 'Call 911 if anyone is hurt, if there is a fire or danger, or if the cars block traffic. Do not move someone with possible neck or back injury unless there is immediate danger such as fire.', 'If it is minor and cars can move, move them out of the traffic lane to a safe place if the law allows.', 'Exchange information with the other driver: name, phone, address, driver license number, plate, insurance company and policy number, vehicle make, model and colour. Do not argue about fault.', 'Take photos: all the vehicles, the damage, plates, the scene with street signs, skid marks, and any injuries. Write down the time, place and the names and numbers of witnesses.', 'Report the crash to police if required in that state or if there is injury, or large damage. Ask for the report number.', 'Call your insurer as soon as you can. A rental car company needs to know too.', 'Get checked by a doctor even if you feel fine; some injuries show up later.', 'Do not sign anything you do not understand, and be careful what you say. Stick to facts.'] },
    { id: 'tow', cat: 'trouble', t: 'Getting towed', sum: 'What to ask before the tow truck leaves.',
      steps: ['Use the tow your assistance plan sends when you can. Check the tow truck company name matches what dispatch told you.', 'Ask where the car will be taken, the cost to tow and to store it, and what payment is accepted.', 'Take photos of the car before it is hooked up. Take valuables, documents and child seats out.', 'Get a receipt or paperwork with the company name and contact number.', 'Arrange where to wait and stay: a safe place for children, not on the roadside. Ask if the tow company will carry passengers.', 'If you have a rental, call the rental company right away; they may arrange a replacement.'] },
    { id: 'flat', cat: 'trouble', t: 'Flat tire', sum: 'Only change a tire where it is safe to do so.',
      steps: ['Pull well off the road onto firm, level ground. Hazards on, parking brake on, car in park. Everyone out and away from the traffic side.', 'If the shoulder is narrow, busy or sloped, drive slowly on the flat to a better spot (this can ruin the tyre but it is better than a roadside change) or call for help instead.', 'Read the manual for where the jack points are. Loosen the wheel nuts slightly while the wheel is on the ground, then jack the car up, remove the nuts, swap the tire.', 'Never put any part of your body under a car held up only by a jack.', 'Tighten the nuts in a star pattern, lower the car, then tighten again fully. Check the spare\'s pressure soon, and observe speed and distance limits printed on a temporary spare.', 'Have the damaged tire fixed or replaced as soon as possible.'] },

    /* ---------------- WEATHER ---------------- */
    { id: 'hot-car', cat: 'weather', t: 'Heat and the parked car', sum: 'Cars heat up fast. Never leave kids or pets.',
      warn: 'Never leave a child or a pet in a parked car, not even for a minute with the windows open. If you see a child or pet alone in a hot car and in distress, call 911.',
      steps: ['The inside of a car can get much hotter than the outside, very quickly.', 'Look before you lock: check the back seat every time you leave the car. Put your bag or phone in the back seat as a reminder.', 'Keep the car locked when parked at home so children cannot climb in.', 'Use sun shades. Cover metal seat belt buckles and dark car seats in the sun, and check them before you buckle a child in.', 'In very hot weather, drive in the cooler hours, carry extra water and know the signs of heat illness: heavy sweating, headache, dizziness, nausea, confusion. Move to shade or air conditioning and cool the person with water. Confusion, fainting or hot dry skin is an emergency: call 911.', 'Watch the temperature gauge. In heat, turn off the air conditioning and run the heater to push heat away from the engine if it starts overheating, and pull over safely.'] },
    { id: 'smoke', cat: 'weather', t: 'Wildfire smoke and fires', sum: 'Check air quality and closures before you go.',
      steps: ['Before and during the trip, look at the local air quality and fire information. Fires can close roads quickly; follow officials\' directions and detours.', 'In smoky air: keep the windows up, set the ventilation to recirculate, and limit time outside. Smoke is hardest on children, older adults, pregnant people and anyone with asthma or heart or lung disease. Keep their medicines handy.', 'A well-fitted N95 or similar respirator helps when you have to be outside. Cloth and paper masks do not filter smoke well.', 'If you see flames or heavy smoke ahead, do not drive into it. Turn around where it is safe. Smoke can suddenly cut visibility to near zero: slow down, lights on, and pull off the road.', 'If told to evacuate, go right away. Do not wait to pack. Take people, pets, documents, medicines and a phone charger.', 'Do not start campfires when fire restrictions are in place; follow the rules posted by the land manager.'] },
    { id: 'flood', cat: 'weather', t: 'Flash floods and water on the road', sum: 'Turn around, don\'t drown.',
      warn: 'Never drive through flooded roadways. You cannot tell how deep the water is or whether the road is still there beneath it. A foot or two of moving water can carry a vehicle away.',
      steps: ['If you see water across the road, turn around and find another way. It is never worth the risk.', 'Most flood deaths in vehicles happen when drivers try to cross. It can be dry where you are while a storm upstream sends a flood down a dry creek bed or canyon.', 'Be especially careful at night, when you cannot see the water.', 'Do not drive around barricades. They are there for a reason.', 'In slot canyons, washes and low-water crossings, check the forecast before you go and avoid them in storms.', 'If your car stalls in rising water, unbuckle, get out immediately and climb to higher ground. If water is trapping you, call 911 and get on the roof only if you must.', 'Check the weather forecast and alerts for your whole route each morning (the National Weather Service is the source in the US).'],
      links: [{ t: 'National Weather Service', u: 'https://www.weather.gov' }] },
    { id: 'snow-ice', cat: 'weather', t: 'Snow and ice on the road', sum: 'See also Winter driving. Slow down and leave space.',
      steps: ['Bridges, overpasses and shaded corners freeze first and can be icy when other roads are not.', 'Black ice looks like wet pavement. If the road is wet and the temperature is near freezing, assume ice.', 'Slow down well before curves. Do not use cruise control on wet, icy or snowy roads.', 'If conditions get worse than you can handle, exit and wait it out. A motel is cheaper than a crash.', 'Look at the DOT road-condition information for the state before and during the day.'] },
    { id: 'wind', cat: 'weather', t: 'High wind', sum: 'Watch for gusts, especially with tall vehicles and trailers.',
      steps: ['Hold the wheel with both hands and expect gusts at bridges, open plains, desert passes and when passing large trucks.', 'Slow down. Tall vehicles, RVs and trailers can be blown about. Think about delaying the trip if high-wind warnings are posted for your route.', 'Watch for debris, branches and downed power lines. Never drive over a power line.', 'In a dust storm or blowing dust, pull off the road as far as you can, turn off lights, and keep your foot off the brake so others do not follow your lights into you. Wait for it to pass.'] },
    { id: 'desert', cat: 'weather', t: 'Desert and hot-weather breakdown', sum: 'Stay with the car. Water is life.',
      warn: 'If your car breaks down in a hot, remote area, stay with the car. A vehicle is much easier to spot than a walker, and it gives shade. Do not set off to walk to find help unless you are sure of exactly how far it is.',
      steps: ['Carry more water than you think you need: at least a gallon per person per day, more in extreme heat. Keep it in the cabin where it is not baking in the trunk.', 'If the car stops: stay in the shade of the vehicle, ideally with a bright cloth or mirror to signal. Sip water regularly instead of saving it for later; staying cool and rested matters more than rationing.', 'Move around in the cooler early or late hours only if you need to do so. Rest in the shade in the heat of the day.', 'Tell someone your route and expected time before you leave, so help knows where to look.', 'Avoid unmarked or unpaved shortcuts that your phone suggests when you have no signal or a low-clearance car.'] },

    /* ---------------- REMOTE ---------------- */
    { id: 'dead-zones', cat: 'remote', t: 'No signal: what to prepare', sum: 'Many beautiful roads have no cell service.',
      steps: ['Assume there will be gaps. Download maps, lodging and ticket details and the route offline before you lose signal.', 'Know that satellite messaging or an emergency beacon is the only way to call for help in some places. Consider one for trips to remote areas, and learn how it works before you go.', 'Pick a "check-in" plan: tell someone where you are going, your route, the time you expect to arrive, and what time to worry and who to call.', 'Keep a paper map and note the distance between towns.', 'Many phones can place an emergency call to 911 even when your carrier has no signal, if any other network is available. Do not count on it.', 'If you have an accident in a dead zone, a driver coming along is often your best hope. Make your car visible and stay with it.'] },
    { id: 'tell-someone', cat: 'remote', t: 'Tell someone your plan', sum: 'The simplest safety tool there is.',
      steps: ['Write down and share: route and roads, vehicle make, colour and plate, who is with you, when you expect to arrive at each stop, and when to call for help.', 'Agree on a "no later than" time and who to call (a local sheriff or park ranger, depending on where you are).', 'Check in as soon as you have signal. Also tell them when you arrive, so they do not worry.', 'Use the Journal tab\'s "Send an update" to do this by text.'] },
    { id: 'fuel-rule', cat: 'remote', t: 'The fuel rule', sum: 'In remote country, fill up at half a tank.',
      steps: ['Where stations are far apart, fill up whenever you pass one and your tank is less than half. Do not wait for the light.', 'Look up the distance to the next station before leaving a town, and add a margin. Stations in small towns may be closed at night or on Sundays, or out of fuel.', 'Unpaved roads, hills, headwinds, heat (air conditioning), heavy loads and towing all reduce your range.', 'Carry extra water, food and a blanket on any road where you could be waiting hours for help.', 'Electric vehicles: plan charging stops with margin and have a back-up charger option. Cold weather and mountains cut range a lot.'] },
    { id: 'dirt-roads', cat: 'remote', t: 'Unpaved and rough roads', sum: 'Know your car and the conditions.',
      steps: ['Check with the land manager (park, forest or BLM office) about the current road condition before leaving the pavement. Rain can turn a dirt road to deep mud or wash it out.', 'Rental contracts often forbid unpaved roads. Check before you go.', 'Slow down. Lower the speed so you can stop for rocks and ruts. Do not rely on a phone map that picks a shortcut.', 'Check your spare tire and have the tools to change a flat. Carry plenty of water.', 'If the road gets worse than the car can handle, turn around while you still can.'] },

    /* ---------------- RV ---------------- */
    { id: 'rv-size', cat: 'rv', t: 'Height, weight and size', sum: 'Know your numbers and keep them on the dash.',
      steps: ['Measure your rig\'s height (including roof air conditioners and antennas), length and width. Write them on a note on the dashboard.', 'Use a route planner that accounts for vehicle height and weight where possible. Many phone navigation apps do not know about low bridges or weight limits for your size. Watch the road signs.', 'Check your weight ratings (your owner\'s manual and the sticker): gross vehicle weight, tow rating and tongue/hitch weight. Do not exceed them. Weigh your loaded rig at a public scale if you can.', 'Some mountain roads and parkways ban or restrict long or tall vehicles. Check the road\'s official page ahead of time.', 'Tunnels and propane: some tunnels do not allow vehicles carrying propane. Check.'] },
    { id: 'towing', cat: 'rv', t: 'Towing: speed, hitching and braking', sum: 'Slower, wider, longer.',
      steps: ['Hitch: coupler fully latched and pinned, safety chains crossed and attached, breakaway cable connected, lights and brake controller tested every time.', 'Load heavier items low and over the axles. Keep a bit more weight in front of the trailer axle than behind for stability, as your manual advises.', 'Drive more slowly than you would alone. Follow the posted speed limits for towing, which can be lower for vehicles with trailers. Leave a much bigger gap in front.', 'Turn wider: the trailer cuts corners. Check mirrors constantly.', 'If the trailer begins to sway, ease off the accelerator, do not brake hard, keep the steering straight, and use the trailer brake controller manually if you have it. Pull over to check the load when it is safe.', 'Use a lower gear on long hills, as in mountain driving.', 'Backing up: have a spotter, go slowly, and place your hand at the bottom of the steering wheel and move it in the direction you want the trailer to go.'] },
    { id: 'rv-camp', cat: 'rv', t: 'Camp set-up and levelling', sum: 'A steady order prevents mistakes.',
      steps: ['Walk the site first to check for low branches, soft ground and slopes. Reverse with a spotter.', 'Level side to side and front to back with blocks or levellers. Chock the wheels before unhitching. Do not rely on the parking brake alone.', 'Connect: electric (check the pedestal breaker is off when plugging in and the amperage fits), water (use a pressure regulator), then sewer. Use a hose rated for drinking water.', 'Retract steps and awnings in wind. Do not leave an awning out when you leave or sleep in a storm.', 'Walk around once before leaving: stabilisers up, steps in, vents closed, hitch locked, nothing plugged in.'] },
    { id: 'propane', cat: 'rv', t: 'Propane and fuelling', sum: 'Follow the manufacturer\'s instructions.',
      warn: 'Propane is heavier than air and can collect low. Never ignore a gas smell: no flames or switches, get everyone out, shut the valve if safe, and call for help. Keep working carbon monoxide and propane alarms in the RV and test them.',
      steps: ['When fuelling the vehicle, turn off propane appliances and pilot lights, as your RV manufacturer instructs. Many manuals say to turn off propane at the tank too.', 'Keep flames, smoking and sparks away from any fuelling. Engine off.', 'Many tunnels and some ferries restrict propane. Check the rules.', 'Have the propane system inspected for leaks if you smell gas or notice anything unusual. A soapy water test on connections can show leaks, but ask a professional if unsure.', 'Never run a generator, grill or heater indoors or near open windows. Carbon monoxide is odourless and deadly.'] },
    { id: 'rv-tires', cat: 'rv', t: 'Tire checks for RVs and trailers', sum: 'Tires are the number one thing to watch.',
      steps: ['Check pressure on every tire, including the spare and the trailer tires, cold, before every travel day. Use the pressure in your manual or on the load-rating sticker.', 'Look at the age. Tires age even when unused; there is a four-digit date code on the sidewall (week and year). Many makers advise replacement after several years regardless of tread. Check your manufacturer\'s advice.', 'Check the sidewalls for cracks and bulges, and the lug nuts for tightness after the first miles on a new wheel installation.', 'Do not overload the tires. Spread weight evenly.', 'A tire pressure monitor for the whole rig gives early warning of a slow leak.'] },
    { id: 'dump', cat: 'rv', t: 'Dump stations and tanks', sum: 'Order matters and so does hygiene.',
      steps: ['Wear disposable gloves. Park so the sewer outlet lines up with the dump hole, and connect the hose securely with the fitting before you open any valve.', 'Empty the black tank (toilet) first, then the grey tank (sinks and shower). The grey water then rinses out the hose.', 'Close the valves, rinse the hose and tidy up, and wash your hands. Keep the drinking water hose separate and never use it for dumping.', 'Find dump stations on your route in advance. Not all campgrounds have them, and some charge a fee. Do not dump anywhere that is not a designated station.', 'Hold tank levels in mind on long trips; do not dump the black tank when almost empty, as solids can build up.'] },
    { id: 'rv-checkin', cat: 'rv', t: 'Campground check-in', sum: 'Call ahead for big rigs.',
      steps: ['Book ahead in busy seasons and tell the campground your rig\'s length, height and slide-outs. Ask about the site\'s length, the electric amperage (30 or 50), hookups and turning room.', 'Know the check-in and check-out times and the quiet hours. Arrive in daylight if possible.', 'If you arrive after hours, ask in advance about late arrival.', 'Follow the posted speed limit in the campground and watch for children.', 'Ask about rules for pets, fires and generators.'] },

    /* ---------------- MONEY ---------------- */
    { id: 'budget', cat: 'money', t: 'Budget per day', sum: 'Count the big four, then add a cushion.',
      steps: ['Fuel: miles per day, divided by your miles per gallon (or per kWh), times the fuel price.', 'Lodging or campsite per night, plus taxes and fees.', 'Food: groceries and a few meals out. A cooler can save a lot.', 'Activities, entrance fees, parking, tolls.', 'Add a cushion of about 10 to 20 percent for surprises: a flat tire, a motel night, a repair.', 'Track as you go: the Trip tab\'s costs help. Check the total at the end of each day.'] },
    { id: 'tolls', cat: 'money', t: 'Tolls and parking', sum: 'Cash lanes are going away in many places.',
      steps: ['Many toll roads are now fully electronic: they read your plate or a transponder and send a bill. Cash may not be accepted at all.', 'Find out each toll road\'s way to pay before you enter. If you have a rental, ask how tolls are billed; some rental companies add a service fee.', 'Pay promptly when you get a bill. Late fees can be much higher than the toll.', 'Your navigation app may offer a "avoid tolls" option. Check how much time it adds.', 'Parking: look for the parking rules signs. Check time limits, permit zones and tow-away signs. Park apps and pay stations are common in cities. Take photos of where you parked and the sign.', 'Never leave valuables visible in a parked car. Put bags in the trunk before you arrive, not when you park.'] },
    { id: 'fuel-save', cat: 'money', t: 'Saving on fuel', sum: 'Small habits add up.',
      steps: ['Use a fuel-price app or website to compare prices before you fill up; prices vary by town and by roadside. Stations right at the highway exit are often more costly. Remote areas often have the highest prices, so fill up before them if you have the range.', 'Drive at steady, moderate speeds. Fuel use rises quickly at higher highway speeds.', 'Remove the roof box when you do not need it. Keep tires at the right pressure. Do not carry extra weight.', 'Plan routes to avoid heavy traffic and stop-start driving.', 'A club or store loyalty card may give fuel discounts; check if it is worth it.'] },
    { id: 'park-pass', cat: 'money', t: 'National park passes', sum: 'One pass can pay for itself on a big trip.',
      warn: 'Pass prices, what is covered and who qualifies change. Check the current details on the National Park Service website (nps.gov) and at the park entrance before you buy. This app does not list prices.',
      steps: ['The "America the Beautiful" pass is a federal recreation pass. It is an annual pass that covers entrance fees at many national parks and other federal recreation lands, for the pass holder and the passengers in one vehicle at per-vehicle fee sites. Check nps.gov for exactly what it covers, current price and any discounted or free versions for certain groups.', 'Not all parks charge an entrance fee. Some charge per person (walk-in or bicycle). Some require a timed entry reservation in busy seasons: check the park\'s own page well ahead.', 'A pass does not cover camping or special tours in most cases.', 'Do the maths: add up the entrance fees of the parks you will visit; compare with the pass price.', 'Many national forests and state parks have their own passes. Check the managing agency.'],
      links: [{ t: 'National Park Service', u: 'https://www.nps.gov' }] },

    /* ---------------- FOOD ---------------- */
    { id: 'cooler', cat: 'food', t: 'Cooler food safety', sum: 'Keep it cold: 40 F (4 C) or below.',
      warn: 'Perishable food (meat, dairy, cut fruit, cooked leftovers) should not stay in the temperature "danger zone" for long. Rule of thumb: no more than 2 hours, or 1 hour if it is hot outside (90 F / 32 C or above). When in doubt, throw it out.',
      steps: ['Chill food in the fridge before you pack it. Pack cold food straight from the fridge.', 'Use plenty of ice or frozen gel packs. A full cooler stays cold longer than a half-empty one. Aim to keep the inside at 40 F (4 C) or below, and check with a cheap fridge thermometer.', 'Pack raw meat in sealed containers on the bottom so juices cannot drip on other food. Keep raw and ready-to-eat foods apart.', 'Keep the cooler in the shaded part of the car, not the trunk, and open it as little as you can. Use a separate cooler for drinks, because it gets opened often.', 'Drain melted water only if you are using ice; keep the food out of standing water.', 'Use clean hands. Bring hand sanitiser or wipes and soap and water where possible.', 'If the ice has all melted and the food has been warm for hours, discard perishable food.'],
      links: [{ t: 'USDA food safety', u: 'https://www.fsis.usda.gov' }] },
    { id: 'picnic', cat: 'food', t: 'Picnic kit', sum: 'A box in the trunk makes every rest stop a meal.',
      check: ['Tablecloth or blanket', 'Plates, cups, cutlery (reusable)', 'Cutting board and knife in a sheath', 'Can/bottle opener', 'Paper towels and wipes', 'Trash bags', 'Hand sanitiser and soap', 'Salt, pepper, oil, sauces in small containers', 'Dish soap and sponge', 'Dish towel', 'Cooler and ice packs', 'Water jug', 'Camp stove only where allowed, with fuel'],
      steps: ['Keep the kit packed and ready in one box.', 'Look for picnic tables at rest areas, parks and viewpoints on your route.', 'Leave the place cleaner than you found it, and pack out all trash.'] },
    { id: 'road-food', cat: 'food', t: 'Eating well on the road', sum: 'Fuel the driver, too.',
      steps: ['Eat lighter meals while driving. Heavy meals can make a driver sleepy.', 'Keep water within reach. Dehydration brings headaches and tiredness.', 'Eat at local places in small towns for a taste of the area. Look at reviews offline from saved lists.', 'Allergies: carry safe food; do not rely on finding something at a stop. Tell restaurants clearly.', 'Do not eat food that has been left out in a hot car.'] },

    /* ---------------- GAMES ---------------- */
    { id: 'games-spot', cat: 'games', t: 'Spotting games (12)', sum: 'Eyes out the window.',
      list: ['Road trip bingo: tick off things you spot (see the Journal tab for printable cards).', 'License plate game: spot plates from every state (Journal tab has the checklist).', 'The alphabet game: find A to Z in order on signs and plates. First to Z wins.', 'Colour car: pick a colour and count cars of that colour for ten minutes.', 'Cow count: count cows on your side; pass a cemetery and lose them all, if you like this old rule.', 'I spy: "I spy with my little eye something that is blue."', 'Number hunt: find 1 to 20 in order on signs, mile markers and plates.', 'Bridge, tunnel, tower: score points for each you see.', 'Animal safari: list every animal you see, real or on a sign.', 'Letter lines: find every letter of a word, one on each sign.', 'Sign story: make up a story that uses the words on the next five signs.', 'Mile-marker guess: guess the next exit number or town. Closest wins.'] },
    { id: 'games-word', cat: 'games', t: 'Word and talk games (12)', sum: 'Good for eyes that need a rest from the view.',
      list: ['Twenty questions: think of something; others ask yes/no questions.', 'Would you rather: pick a silly choice and say why.', 'Story chain: each person adds one sentence to a growing story.', 'Categories: pick a category, take turns naming something in it until someone is stuck.', 'Word chain: the next word starts with the last letter of the previous word.', 'Rhyme time: one person says a word, others take turns with rhymes.', 'The suitcase game: "I packed my bag and in it I put…", adding items and remembering the list.', 'Hum that tune: hum a song and the others guess it.', 'Two truths and a lie: about your summer, school or the trip.', 'Name that animal: describe an animal in hints, from hard to easy.', 'Spell it with a twist: spell a word backwards in your head.', 'Trivia tour: ask questions about the places you are driving through.'] },
    { id: 'games-silly', cat: 'games', t: 'Silly, creative and quiet (12)', sum: 'For the afternoon slump.',
      list: ['Trip diary: draw or write one thing from each day.', 'Postcard writing: write a postcard to a friend at each stop.', 'Kids\' tour guide: a child narrates the next sight as if on TV.', 'Silent game: nobody speaks; first to speak loses.', 'Drawing relay: draw a few lines, pass the paper, add to it.', 'Dot-to-dot, tic-tac-toe, hangman or dots and boxes on paper.', 'Make a playlist: each person picks a song in turn.', 'Podcast or audio-story hour.', 'Sticker scene: build a scene on a sticker sheet.', 'Mad-libs: make up a story by supplying nouns and verbs.', 'Snack scavenger: find a snack of each colour at the next store stop.', 'Photo mission: take five photos of things that start with the same letter.'] },
    { id: 'games-rules', cat: 'games', t: 'Keeping the peace', sum: 'A few rules help the whole car.',
      steps: ['Take turns picking the game and the music.', 'Keep the driver\'s concentration in mind: games with shouting or complicated rules are for when the driver is not tired. The driver may sit out.', 'Mix: one active game, one quiet game, then a break.', 'If a game turns into a fight, change it. The aim is fun.', 'Set a prize: first to spot 10 cows chooses the next stop snack.'] },

    /* ---------------- PACKING ---------------- */
    { id: 'pack-weekend', cat: 'pack', t: 'Packing: weekend trip', sum: 'Light and quick.',
      check: ['Clothes for 2-3 days, with one layer extra', 'Underwear and socks for each day', 'Toiletries and medicines', 'Phone, charger, power bank', 'Wallet, license, insurance card', 'Water bottle and snacks', 'Sunglasses and sunscreen', 'Rain jacket', 'Swimsuit if there is water', 'Camera', 'Book or playlist', 'Trash bag and wipes'] },
    { id: 'pack-parks', cat: 'pack', t: 'Packing: national parks', sum: 'Layers, water, paper maps.',
      check: ['Park pass and reservations printed', 'Hiking shoes and spare socks', 'Layers for hot days and cold nights', 'Rain jacket', 'Hat, sunglasses, sunscreen', 'Day pack with water for each person', 'Snacks and a picnic', 'Park map and a paper road atlas', 'Headlamp or flashlight', 'First-aid kit', 'Bug spray', 'Binoculars', 'Bear-safe food storage if required', 'Camera and spare battery', 'Extra water in the car'] },
    { id: 'pack-beach', cat: 'pack', t: 'Packing: beach trip', sum: 'Sun, sand and shade.',
      check: ['Swimsuits (2 each)', 'Towels', 'Sunscreen (reapply often)', 'Sun hats and sunglasses', 'Beach umbrella or shade tent', 'Cooler with ice packs and plenty of water', 'Sand toys', 'Flip-flops', 'Cover-ups and rash guards', 'After-sun lotion', 'Dry bag for phones and keys', 'Trash bags', 'Beach chairs', 'Change of clothes in a bag', 'Check local rules about flags and rip currents'] },
    { id: 'pack-winter', cat: 'pack', t: 'Packing: winter trip', sum: 'Warm in the car and out of it.',
      check: ['Winter coats, hats, gloves, scarves', 'Waterproof boots and extra socks', 'Base layers', 'Blanket for every person in the car', 'Ice scraper, snow brush and small shovel', 'Chains or traction devices as required, practised', 'Jumper cables or jump starter', 'Flashlight and spare batteries', 'Sand or cat litter for traction', 'Thermos and snacks', 'Phone charger and power bank', 'Hand warmers', 'Lip balm and moisturiser', 'Washer fluid rated for cold', 'Full tank before mountains'] },
    { id: 'pack-kids', cat: 'pack', t: 'Packing: trip with young kids', sum: 'More than you think, in reach.',
      check: ['Car seats (installed and checked)', 'Diapers and wipes, extra', 'Change of clothes for each child (in the cabin)', 'Blankets and comfort toys', 'Sick bags and a towel', 'Child medicines the doctor approved and a thermometer', 'Sunscreen and hats', 'Snacks, bottles, sippy cups', 'Travel high chair or booster if needed', 'Stroller or carrier', 'Activity bags', 'Night light or white noise for hotels', 'Baby monitor', 'Birth certificates or documents if needed', 'Plug covers and outlet safety for rentals'] },
    { id: 'pack-rv', cat: 'pack', t: 'Packing: RV or camper', sum: 'Move-in kit.',
      check: ['Leveling blocks and wheel chocks', 'Water hose (drinking-water rated) and pressure regulator', 'Sewer hose and gloves', 'Power adapters (30/50 amp)', 'Tool kit and tire pressure gauge', 'Bedding and towels', 'Kitchen basics, cooler', 'Propane check and spare cylinder if used', 'Fire extinguisher', 'Carbon monoxide and propane alarms (test)', 'First-aid kit', 'Camp chairs and outdoor mat', 'Flashlights', 'Trash bags', 'Paper campground and route info'] },

    /* ---------------- SCENIC (general, not source-checked) ---------------- */
    { id: 'sc-pch', cat: 'scenic', gen: true, t: 'Pacific Coast Highway (California Route 1)', sum: 'A coastal drive along California\'s edge.',
      warn: 'Stretches of Highway 1 through the Big Sur coast have been closed at times by landslides and storm damage. Before you plan the drive, check the current status with Caltrans (the California Department of Transportation) road-condition information. This app does not have closure dates or phone numbers.',
      steps: ['A famous road that follows much of California\'s coast. It is a winding two-lane in many places, with curves and sheer drops.', 'Plan more time than the map suggests. Pullouts for views are everywhere; use them rather than stopping in the road.', 'Fuel, food and cell service can be sparse in the remote sections. Fill up before the rural stretches.', 'Fog and rain can reduce visibility. Rockfalls and slides can occur on the cliffs, mostly in winter and spring.', 'Alternative: US-101 inland route is the main highway when Highway 1 is closed.'] },
    { id: 'sc-66', cat: 'scenic', gen: true, t: 'Historic Route 66', sum: 'The old road from Chicago to Southern California.',
      steps: ['A classic cross-country route linking Chicago and the Los Angeles area. The highway was officially removed from the US highway system in 1985, but many sections can still be driven and are signed as "Historic Route 66".', 'Because it is made of many sections, use a dedicated route guide or map for your direction. Some parts are paved old alignments, some are gravel.', 'Look for old diners, neon signs, motels and roadside attractions. Many small businesses are seasonal; call ahead.', 'Check the road condition and local advice for the unpaved or remote sections, particularly in the desert in summer.'] },
    { id: 'sc-keys', cat: 'scenic', gen: true, t: 'Overseas Highway (US-1, Florida Keys)', sum: 'A highway over islands and bridges.',
      steps: ['US-1 runs from the Florida mainland south through the Keys, over many bridges, to Key West. Distances are marked by mile markers that count down toward Key West.', 'Traffic can be heavy on weekends and holidays and when there is an accident; it is mostly a single road, so a crash can cause long waits.', 'Hurricane season (roughly June to November) brings the risk of evacuation and closure. Check the forecast and follow official evacuation orders.', 'Book lodging early in busy season.'] },
    { id: 'sc-blueridge', cat: 'scenic', gen: true, t: 'Blue Ridge Parkway', sum: 'A slow, scenic mountain road through Virginia and North Carolina.',
      steps: ['A park road managed by the National Park Service. It is a slow road with a low speed limit, no commercial trucks and many overlooks.', 'Parts can close because of ice, snow, fog or storm damage, especially in winter. Check the current road status on the National Park Service website before you go.', 'Services (fuel, food, lodging) can be far apart. Fill up before you enter and plan stops at nearby towns.', 'Fall colour season is popular; lodging fills up early.'] },
    { id: 'sc-tioga', cat: 'scenic', gen: true, t: 'Tioga Road (Highway 120, Yosemite)', sum: 'A high mountain crossing in the Sierra Nevada, open only in the warm months.',
      warn: 'This high mountain road closes for the winter because of snow, and may close at other times for snow or fire. The opening and closing dates vary every year. Check current road status with the National Park Service (Yosemite page) and Caltrans before you plan.',
      steps: ['The road climbs to high elevation. Take it slowly and watch the engine temperature on the climbs.', 'Fuel and services are limited along the high stretch. Fill up before.', 'Afternoon thunderstorms can occur in summer in high country. Altitude can affect people; drink water and rest.', 'A park entrance fee or reservation system may apply to entering Yosemite. Check the park website.'] },
    { id: 'sc-gts', cat: 'scenic', gen: true, t: 'Going-to-the-Sun Road (Glacier National Park)', sum: 'A famous high road in Montana, open only after the snow melts.',
      warn: 'The full road is open only for part of the year, depending on snow clearing. Some vehicles over a certain size are restricted on parts. A timed-entry or vehicle reservation system has been used at times. Check the National Park Service Glacier pages for current rules, closures and size limits before you go.',
      steps: ['A narrow, winding mountain road with steep drop-offs, and few guardrails in places.', 'Plan to start early; parking at the pass fills in the morning.', 'Weather changes quickly in the mountains. Bring layers.', 'Be bear aware in the park and follow ranger advice.'] },
    { id: 'sc-mtn', cat: 'scenic', gen: true, t: 'High mountain roads (Beartooth, Trail Ridge, Million Dollar Highway)', sum: 'Spectacular, seasonal and weather-dependent.',
      warn: 'High mountain roads in the western US can close for snow in all but the warmest months, and some can close in summer too. Check the state DOT or park road-condition information for the day you drive.',
      steps: ['These are well-known high passes in Montana and Wyoming (Beartooth Highway), Colorado (Trail Ridge Road in Rocky Mountain National Park; the Million Dollar Highway section of US-550).', 'Expect steep grades, curves, drop-offs, thin air, and fast-changing weather, including snow in summer at the highest points.', 'Do not rely on phone navigation; services and signal are limited. Fill up before.', 'Use low gear on the descents.'] },
    { id: 'sc-natchez', cat: 'scenic', gen: true, t: 'Natchez Trace Parkway', sum: 'A quiet, slow national park road through the Southeast.',
      steps: ['A National Park Service parkway running from Natchez, Mississippi, northeast to Nashville, Tennessee. Low speed limit, no commercial traffic, no billboards.', 'Stops to see history, trails and small sights. Fuel and food are in towns off the parkway, which may be a few miles away, so plan ahead.', 'Check the NPS site for any closures or detours. Deer are common at dawn and dusk.'] },
    { id: 'sc-plan', cat: 'scenic', t: 'Planning any scenic drive', sum: 'The same checks apply to all.',
      steps: ['Check the road\'s status the day before and the morning of: open or closed, one lane, chain control, fire or slide.', 'Allow double the map\'s drive time for winding roads with lots of stops.', 'Have fuel, water and food. Stations can be far apart.', 'Tell someone your route if you will be out of signal.', 'Use pullouts for photos; never stop in a lane or on a blind curve.', 'Be ready to turn around if conditions are poor. The view will be there another day.'] }
  ]
};
